<template><div class="page-heading"><div><h1>今天的课</h1><p>{{ data ? date(data.today,{weekday:'long'}) : '把每一节课，轻松记下来。' }}</p></div><RouterLink class="button primary" to="/coach/lessons/new/"><Icon name="plus" />记一节课</RouterLink></div><div class="actions"><RouterLink class="button secondary" to="/coach/lessons/batch/">批量记课 / 小班结算</RouterLink><RouterLink class="text-link" to="/coach/reports/">查看月报</RouterLink></div><ResourceState :error="error" :loading="loading && !data" @retry="refresh" /><template v-if="data"><div class="summary-line"><span>今天已记 <strong>{{ data.recorded_today }}</strong> 节</span><span>待确认 <strong>{{ data.unconfirmed_count }}</strong> 节</span><RouterLink to="/coach/students/">{{ data.student_count }} 位学员 <Icon name="arrow" /></RouterLink></div><section v-if="data.unconfirmed.length" class="section"><div class="section-heading"><h2>课后确认</h2><span class="muted">确认后自动同步课时</span></div><div class="surface list-surface"><RouterLink v-for="item in data.unconfirmed" :key="item.id" :to="`/coach/bookings/${item.id}/`" class="list-row"><div class="avatar">{{ item.student?.name.slice(0,1) }}</div><div class="grow"><h3>{{ item.student?.name }}</h3><p>{{ date(item.session.start) }} · {{ time(item.session.start) }} · {{ item.session.title }}</p></div><span class="text-link">去确认</span><Icon name="arrow" /></RouterLink></div><RouterLink v-if="data.unconfirmed_count>10" class="text-link" to="/coach/bookings/?status=booked">查看全部待确认</RouterLink></section><section class="section"><div class="section-heading"><h2>最近记课</h2><RouterLink class="text-link" to="/coach/lessons/">全部记录</RouterLink></div><div class="surface list-surface"><LessonList :items="data.recent_lessons" coach /></div></section><section class="section"><div class="section-heading"><h2>今天的安排</h2><RouterLink class="text-link" to="/coach/sessions/">排课</RouterLink></div><div class="surface list-surface"><p v-if="!data.sessions.length" class="empty-note">今天没有系统排课，线下上的课也可以直接记录。</p><RouterLink v-for="item in data.sessions" :key="item.id" :to="`/coach/sessions/${item.id}/`" class="list-row"><div class="time-column"><strong>{{ time(item.start) }}</strong><small>{{ time(item.end) }}</small></div><div class="grow"><h3>{{ item.title }}</h3><p>{{ item.location }} · {{ kinds[item.kind] }}</p></div><span class="badge">{{ item.occupied }} / {{ item.capacity }} 人</span><Icon name="arrow" /></RouterLink></div></section><details v-if="data.pending_count" class="secondary-section"><summary>课后指导 · {{ data.pending_count }} 份待点评</summary><RouterLink v-for="item in data.pending" :key="item.submission_id" :to="`/coach/plans/${item.plan_id}/`" class="list-row"><div class="grow"><h3>{{ item.student_name }}</h3><p>{{ item.title }}</p></div><Icon name="arrow" /></RouterLink></details></template></template>
